def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if len(comp) != 4:
                continue
            min_r = min(y for y, x in comp)
            max_r = max(y for y, x in comp)
            min_c = min(x for y, x in comp)
            max_c = max(x for y, x in comp)

            if max_c - min_c == 2 and max_r - min_r == 1:
                if sum(y == min_r for y, x in comp) == 1:
                    up += 1
                else:
                    down += 1

    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for count, color, offset in ((up, 3, 0), (down, 1, 3)):
        for r, c in slots[:count]:
            out[r][c + offset] = color
    return out
